function solve(nums) {
  if (nums.length <= 1) return nums.slice();
  const pivot = nums[Math.floor(nums.length / 2)];
  const left = [], mid = [], right = [];
  for (const v of nums) {
    if (v < pivot) left.push(v);
    else if (v > pivot) right.push(v);
    else mid.push(v);
  }
  return [...solve(left), ...mid, ...solve(right)];
}
